from collections import deque
def transform(grid):
    a=[r[:] for r in grid]; h=len(a); w=len(a[0]); bg=max(set(x for r in a for x in r), key=lambda c:sum(r.count(c) for r in a))
    seen=set()
    for i in range(h):
      for j in range(w):
        c=a[i][j]
        if c==bg or (i,j) in seen: continue
        q=[(i,j)]; seen.add((i,j)); comp=[]
        while q:
          y,x=q.pop(); comp.append((y,x))
          for yy,xx in ((y+1,x),(y-1,x),(y,x+1),(y,x-1)):
            if 0<=yy<h and 0<=xx<w and a[yy][xx]==c and (yy,xx) not in seen: seen.add((yy,xx)); q.append((yy,xx))
        ys=[y for y,x in comp]; xs=[x for y,x in comp]; t,b=min(ys),max(ys); l,r=min(xs),max(xs)
        if len(comp)==(b-t+1)*2+2*(r-l-1) and b-t>=2 and r-l>=2:
          fill=7 if (b-t+1)%2==1 and (r-l+1)%2==1 else 2
          for y in range(t+1,b):
            for x in range(l+1,r):
              if a[y][x]==bg:a[y][x]=fill
    return a
